import fs from 'node:fs';

for (const path of ['src/index.css', 'src/website.css']) {
  let source = fs.readFileSync(path, 'utf8');
  source = source.replaceAll('rgb(0 0 0 / .25)', 'var(--shadow)')
    .replaceAll('rgb(0 229 255 / .08)', 'rgb(73 131 208 / .08)')
    .replaceAll('rgb(13 19 28 / .94)', 'rgb(255 255 255 / .94)')
    .replaceAll('rgb(5 7 10 / .96)', 'rgb(255 255 255 / .96)')
    .replaceAll('rgb(0 0 0 / .72)', 'rgb(27 48 77 / .45)');
  fs.writeFileSync(path, source);
}

const path = 'src/pages/website.tsx';
const colors = {
  '#172332': '#e3f3fa', '#22364a': '#cdebf5', '#149aad': '#4983d0', '#075366': '#2e67b2',
  '#abc7d8': '#ffffff', '#548397': '#d9edf8', '#142231': '#edf5fa', '#101b28': '#e2edf5',
  '#36576b': '#a9cce5', '#799ba9': '#ffffff', '#304d68': '#a6cce3', '#63d8ed': '#ffffff',
  '#05070a': '#a9bed0', '#273d52': '#667c95', '#117e92': '#3677c8', '#31b9c9': '#6499df',
  '#a8c9d6': '#ffffff', '#688ea6': '#c7d9ec', '#5d7990': '#cc3396', '#44778c': '#5078aa',
  '#4e9aaf': '#789dc8', '#4a6076': '#70849c', '#50738b': '#aac7e2', '#668ba1': '#c7dff1',
  '#d8e8ef': '#ffffff', '#c2d8e4': '#ffffff', '#48768a': '#b5d4ea', '#00e5ff': '#cc3396',
  '#2b4c62': '#bddcf0', '#223b50': '#ccdeeb', '#b4cddc': '#ffffff',
};
fs.writeFileSync(path, fs.readFileSync(path, 'utf8').replace(/#[\da-f]{6}\b/gi, (color) => colors[color] || color));
